import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"61、【中孚】 兌下巽上","description":"周易集註 - 61、【中孚】 兌下巽上","frontmatter":{"title":"61、【中孚】 兌下巽上","description":"周易集註 - 61、【中孚】 兌下巽上"},"headers":[],"relativePath":"classics/jizhu/065.md","filePath":"classics/jizhu/065.md"}'),l={name:"classics/jizhu/065.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_61、【中孚】-兌下巽上" tabindex="-1">61、【中孚】 兌下巽上 <a class="header-anchor" href="#_61、【中孚】-兌下巽上" aria-label="Permalink to “61、【中孚】 兌下巽上”">​</a></h1><p>孚，信也。為卦二陰在內，四陽在外，而二五之陽皆得其中。以一卦六爻言之，為中虛;以二體之二五言之，為中實，皆孚之象也，又下說以應上，上巽以順下，亦有孚義，《序卦》：節而信之，故受之以中孚，所以次節。</p><p>豚魚，生於大澤之中，將生風則先出拜，乃信之自然無所勉強者也。《唐詩》雲“河豚吹浪夜還風”是也。信如豚魚則吉矣，本卦上風下澤，豚魚生於澤，知風，故象之。鶴知秋，雞知旦，二物皆信，故卦爻皆象之。利貞者，利於正也。若盜賊相約，男女相私，豈不彼此有孚，然非理之正矣，故利貞。</p><p>《彖》曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。</p><p>以卦體卦德卦象釋卦名卦辭。二柔在內而中虛，二剛居中而中實，虛則內欲不萌，實則外誘不入，此中孚之本體也。而又下說上順，上下交孚，所以孚乃化邦也。若徙木立信，乃出於矯強矣，安能化邦。《易舉正》止有“信及也”三字，無“豚魚”二字。及者至也，言信至於豚魚，則信出自然矣。如此信，此所以吉也。乘木舟虛者，本卦外實中虛，有舟虛之象。至誠以涉險，如乘巽木之空，以行乎兌澤之上，又豈有沉溺之患，所以利涉大川。應乎天者，信能正，則事事皆天理，所謂誠者天之道也。貞應乎天，所以利貞。</p><h3 id="《象》曰-澤上有風-中孚-君子以議獄緩死。" tabindex="-1">《象》曰：澤上有風，中孚，君子以議獄緩死。 <a class="header-anchor" href="#《象》曰-澤上有風-中孚-君子以議獄緩死。" aria-label="Permalink to “《象》曰：澤上有風，中孚，君子以議獄緩死。”">​</a></h3><p>聖人之於卦，以八卦為之體，其所變六十四卦中，錯之綜之，上之下之，皆其卦也。如火雷噬嗑，文王之意，以有火之明，雷之威，方可用獄。孔子《大象》言用獄者五，皆取雷火之意，豐取其雷火也，旅與賁，艮綜震，亦雷火也，解則上雷而中爻為火也，下體錯離，亦火也。此卦則大象為火，而中爻為雷也。蓋孔子於易，韋編三絕，胸中之義理無窮，所以無往而非其八卦。不然，風澤之與議獄緩死何相干涉?《易經》一錯一綜，大象中爻，觀此五卦，自能默悟。兌為口舌，議之象。巽為不果，緩之象。</p><p>議獄緩死者，議獄罪當死矣，乃緩其死而欲求其生也。風入水受者，中孚之象也。議獄緩死，則至誠惻怛之意溢於用刑之間矣。</p><p>初九，虞吉，有他不燕。</p><p>虞者樂也安也，燕者喜也安也，二字之義相近。有他者，其志不定而他求其所應也。本卦三四皆陰爻，六三則陰柔不正，六四則得八卦之正位者，因有此陰柔不正者隔於其中，故周公方設此有他之戒。若論本爻應爻，足不容戒也。</p><p>初九陽剛得正，而上應六四，四蓋柔順得正者也，當中孚之初，其志未變，故有與六四相信而安樂之象。佔者如是則吉，若不信於六四，而別信於他，則是不能安樂其中孚矣。故戒佔者如此。</p><h3 id="《象》曰-初九虞吉-志未變也。" tabindex="-1">《象》曰：初九虞吉，志未變也。 <a class="header-anchor" href="#《象》曰-初九虞吉-志未變也。" aria-label="Permalink to “《象》曰：初九虞吉，志未變也。”">​</a></h3><p>方初，中孚之志未變。</p><p>九二，鳴鶴在陰，其子和之;我有好爵，吾與爾靡之。和去聲</p><p>大象離，雉象，變震，鵠象，皆飛鳥之象也。不言雉鵠而言鶴者，鶴信故也。鶴八月霜降則鳴，兌乃正秋，故以鶴言之。中孚錯小過之遺音，又兌為口舌，鳴之象也。故謙豫二卦，象小過皆言鳴。在陰者，鶴行依洲嶼，不集林木，九居陰爻，在陰之象也。巽為長女，兌為少女，子母之象也。好爵者懿德也，陽德居中，故曰好爵。</p><p>子與爾皆指五<em>，因中孚感應極至，而無以加，所以不論君臣，皆呼子爾也。言懿德人之所好，故好爵雖我之所有，而彼亦繫戀之也。物之相愛者若</em>如子母之同心，人之所慕者莫如好爵之可貴，鶴鳴子和者，天機之自動也。好爵爾靡者，天理之自孚也。靡與縻同，繫戀也。巽為繩，系之象也。</p><p>九二以剛中居下，有中孚之實。而九五剛中居上，亦以中孚之實應之，故有此象。佔者有是德，方有是感應也。</p><ul><li><p>原文闕“子”字，依他本補。</p></li><li><p>若或作“莫”。</p></li></ul><h3 id="《象》曰-其子和之-中心願也。" tabindex="-1">《象》曰：其子和之，中心願也。 <a class="header-anchor" href="#《象》曰-其子和之-中心願也。" aria-label="Permalink to “《象》曰：其子和之，中心願也。”">​</a></h3><p>誠意所願，非九二求於九五也。</p><p>六三，得敵，或鼓或罷，或泣或歌。</p><p>得敵者，得對敵也，指上九之應也。言六三不正，上九亦不正也。陰陽皆位不當，所以曰得敵。巽為進退，為不果，作止之象。又中爻震為鼓，鼓之象。艮為止，罷之之象。本卦大象離錯坎，坎為加憂，泣之象。兌為口舌，為巫，歌之象。</p><p>六三陰柔不正，而上應九之不正，此為悅之極，彼為信之窮，皆相敵矣。是以或鼓或罷，而作止不定。或泣或歌，而哀樂無常。其象如此，佔者不能孚信可知矣。</p><h3 id="《象》曰-或鼓或罷-位不當也。" tabindex="-1">《象》曰：或鼓或罷，位不當也。 <a class="header-anchor" href="#《象》曰-或鼓或罷-位不當也。" aria-label="Permalink to “《象》曰：或鼓或罷，位不當也。”">​</a></h3><p>陰居陽位。</p><p>六四，月幾望，馬匹亡，無咎*。</p><p>月幾望者，月與日對而從乎陽也。本卦下體兌，中爻震，震東兌西，日月相對，故幾望。曰幾者，將望而猶未望也。因四陰爻，近五陽爻，故有此日月之象。馬匹亡者，震為馬，馬之象也。此爻變，中爻成離牛，不成震馬矣，馬匹亡之象也。匹者配也，指初九也。曰亡者，不與之交，而絕其類也。無咎者心事光明也。</p><p>六四當中孚之時，近君之位，柔順得正，而中孚之實德，惟精白以事君，不繫戀其黨與者也，故有月幾望馬匹亡之象。佔者能是，則無咎矣。</p><ul><li>原文闕“無”字。</li></ul><h3 id="《象》曰-馬匹亡-絕類上也。" tabindex="-1">《象》曰：馬匹亡，絕類上也。 <a class="header-anchor" href="#《象》曰-馬匹亡-絕類上也。" aria-label="Permalink to “《象》曰：馬匹亡，絕類上也。”">​</a></h3><p>絕其類應而上從五也。</p><p>九五，有孚攣如，無咎。</p><p>攣如，即鶴鳴子和，我爵爾靡也。靡字與攣字，皆有固結而不可解之意。縻者繫戀也，攣者相連也。如合九二，共成一體。包二陰以成中孚，故有此象。若以人事論，乃委用專，而信任篤，虞庭之賡歌，有商之一德是也。無咎者，上下交而德業成也。</p><p>九五居尊位，為中孚之主，剛健中正，有中孚之實德，而下應九二，與之同德相信，故其象佔如此。</p><h3 id="《象》曰-有孚攣如-位正當也。" tabindex="-1">《象》曰：有孚攣如，位正當也。 <a class="header-anchor" href="#《象》曰-有孚攣如-位正當也。" aria-label="Permalink to “《象》曰：有孚攣如，位正當也。”">​</a></h3><p>與履不同，履周公爻辭乃貞厲，此則無咎。</p><p>上九，翰音登於天，貞兇。</p><p>《禮記》雞曰翰音，而此亦曰翰音者，以巽為雞也。因錯小過，飛鳥遺之音，故九二曰鶴鳴，而此曰翰音也。雞信物，天將明則鳴，有中孚之意。巽為高，登天之象也。又居天位，亦登天之象也。《禮記》注：翰長也。雞肥則音長。考諸韻，無長字之義，蓋翰羽也，雞鳴則振拍其羽，故曰翰音，則翰音即雞鳴二字也。登者升也，言雞鳴之聲，登聞於天也。雞鳴本信，但鳴未幾而天明，不能信之長久。巽進退不果，不長久之象也。九二上孚於五，在陰而子和，上九不下孚於三，翰音反登天，其道蓋相反矣。貞者信，本正理也。</p><p>上九居中孚之極，極則中孚變矣。蓋聲聞過情，不能長久於中孚者也，故有此象。佔者得此，貞亦兇矣。</p><h3 id="《象》曰-翰音登於天-何可長也。" tabindex="-1">《象》曰：翰音登於天，何可長也。 <a class="header-anchor" href="#《象》曰-翰音登於天-何可長也。" aria-label="Permalink to “《象》曰：翰音登於天，何可長也。”">​</a></h3><p>言不能鳴之長登於天，不過天將明，一時而已。</p>',41)])])}const m=e(l,[["render",t]]);export{_ as __pageData,m as default};
